import{_ as p,a0 as h,w as o,s as r,ao as l,I as e,x as i,a1 as n,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何使用 SSHFS 通過 SSH 掛載遠程的 Linux 文件系統或者目錄 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 SSHFS 通過 SSH 掛載遠程的 Linux 文件系統或者目錄 | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 SSHFS 通過 SSH 掛載遠程的 Linux 文件系統或者目錄 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 SSHFS 通過 SSH 掛載遠程的 Linux 文件系統或者目錄 | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160811 How to Mount Remote Linux Filesystem or Directory Using SSHFS Over SSH","title":"如何使用 SSHFS 通過 SSH 掛載遠程的 Linux 文件系統或者目錄","tag":"201610","desc":""},"relativePath":"201610/20160811 How to Mount Remote Linux Filesystem or Directory Using SSHFS Over SSH.md","filePath":"[post].md"}'),d={name:"201610/20160811 How to Mount Remote Linux Filesystem or Directory Using SSHFS Over SSH.md"};function u(m,s,g,c,S,f){const t=h("Link");return o(),r("div",null,[s[19]||(s[19]=l('<h1 id="如何使用-sshfs-通過-ssh-掛載遠程的-linux-文件系統或者目錄" tabindex="-1">如何使用 SSHFS 通過 SSH 掛載遠程的 Linux 文件系統或者目錄 <a class="header-anchor" href="#如何使用-sshfs-通過-ssh-掛載遠程的-linux-文件系統或者目錄" aria-label="Permalink to “如何使用 SSHFS 通過 SSH 掛載遠程的 Linux 文件系統或者目錄”">​</a></h1><p>寫這篇文章的主要目的就是提供一步一步的指導，關於如何使用 SSHFS 通過 SSH 掛載遠程的 Linux 文件系統或目錄。</p><p>這篇文章對於那些無論出於什麼目的，希望在他們本地的系統中掛載遠程的文件系統的用户或者系統管理員有幫助。我們通過 Linux 系統中的一個安裝了 SSHFS 客户端進行實際測試，並且成功的掛載了遠程的文件系統。</p><p>在我們進一步安裝之前，讓我們瞭解一下 SSHFS 的相關內容，以及它是如何工作的。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2012/08/Sshfs-Mount-Remote-Linux-Filesystem-Directory.png" alt=""><em>Sshfs 掛載遠程的 Linux 文件系統或者目錄</em></p><h3 id="什麼是-sshfs" tabindex="-1">什麼是 SSHFS？ <a class="header-anchor" href="#什麼是-sshfs" aria-label="Permalink to “什麼是 SSHFS？”">​</a></h3><p>SSHFS（Secure SHell FileSystem）是一個客户端，可以讓我們通過 SSH 文件傳輸協議（SFTP）掛載遠程的文件系統並且在本地機器上和遠程的目錄和文件進行交互。</p><p>SFTP 是一種通過 SSH 協議提供文件訪問、文件傳輸和文件管理功能的安全文件傳輸協議。因為 SSH 在網絡中從一台電腦到另一台電腦傳輸文件的時候使用數據加密通道，並且 SSHFS 內置在 FUSE（用户空間的文件系統）內核模組，允許任何非特權用户在不修改內核代碼的情況下創建他們自己的文件系統。</p><p>在這篇文章中，我們將會向你展示在任意 Linux 發行版上如何安裝並且使用 SSHFS 客户端，在本地 Linux 機器上掛載遠程的 Linux 文件系統或者目錄。</p><h4 id="步驟1-在-linux-系統上安裝-sshfs" tabindex="-1">步驟1：在 Linux 系統上安裝 SSHFS <a class="header-anchor" href="#步驟1-在-linux-系統上安裝-sshfs" aria-label="Permalink to “步驟1：在 Linux 系統上安裝 SSHFS”">​</a></h4>',10)),e("p",null,[s[1]||(s[1]=i("默認情況下，sshfs 包不存在所有的主流 Linux 發行版中，你需要在你的 Linux 系統中啓用 ",-1)),n(t,{href:"https://linux.cn/article-2324-1.html"},{default:a(()=>[...s[0]||(s[0]=[i("epel 倉庫",-1)])]),_:1}),s[2]||(s[2]=i("，在 Yum 命令列的幫助下安裝 SSHFS 及其依賴。",-1))]),s[20]||(s[20]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install sshfs</span></span>
<span class="line"><span># dnf install sshfs              【在 Fedora 22+ 發行版上】</span></span>
<span class="line"><span>$ sudo apt-get install sshfs     【基於 Debian/Ubuntu 的系統】</span></span></code></pre></div><h4 id="步驟2-創建-sshfs-掛載目錄" tabindex="-1">步驟2：創建 SSHFS 掛載目錄 <a class="header-anchor" href="#步驟2-創建-sshfs-掛載目錄" aria-label="Permalink to “步驟2：創建 SSHFS 掛載目錄”">​</a></h4><p>當你安裝 SSHFS 包之後，你需要創建一個掛載點目錄，在這兒你將要掛載你的遠程文件系統。例如，我們在 /mnt/tecmint 下創建掛載目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mkdir /mnt/tecmint</span></span>
<span class="line"><span>$ sudo mkdir /mnt/tecmint     【基於 Debian/Ubuntu 的系統】</span></span></code></pre></div><h3 id="步驟-3-使用-sshfs-掛載遠程的文件系統" tabindex="-1">步驟 3：使用 SSHFS 掛載遠程的文件系統 <a class="header-anchor" href="#步驟-3-使用-sshfs-掛載遠程的文件系統" aria-label="Permalink to “步驟 3：使用 SSHFS 掛載遠程的文件系統”">​</a></h3><p>當你已經創建你的掛載點目錄之後，現在使用 root 用户運行下面的命令列，在 /mnt/tecmint 目錄下掛載遠程的文件系統。視你的情況掛載目錄可以是任何目錄。</p><p>下面的命令列將會在本地的 /mnt/tecmint 目錄下掛載一個叫遠程的一個 /home/tecmint 目錄。（不要忘了使用你的 IP 地址和掛載點替換 x.x.x.x）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sshfs tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint</span></span>
<span class="line"><span>$ sudo sshfs -o allow_other tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint      【基於 Debian/Ubuntu 的系統】</span></span></code></pre></div><p>如果你的 Linux 服務器配置為基於 SSH 密鑰授權，那麼你將需要使用如下所示的命令列指定你的公共密鑰的路徑。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># sshfs -o IdentityFile=~/.ssh/id_rsa tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint</span></span>
<span class="line"><span>$ sudo sshfs -o allow_other,IdentityFile=~/.ssh/id_rsa tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint     【基於 Debian/Ubuntu 的系統】</span></span></code></pre></div><h4 id="步驟-4-驗證遠程的文件系統掛載成功" tabindex="-1">步驟 4：驗證遠程的文件系統掛載成功 <a class="header-anchor" href="#步驟-4-驗證遠程的文件系統掛載成功" aria-label="Permalink to “步驟 4：驗證遠程的文件系統掛載成功”">​</a></h4><p>如果你已經成功的運行了上面的命令並且沒有任何錯誤，你將會看到掛載在 /mnt/tecmint 目錄下的遠程的文件和目錄的列表</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cd /mnt/tecmint</span></span>
<span class="line"><span># ls</span></span>
<span class="line"><span>[root@ tecmint]# ls</span></span>
<span class="line"><span>12345.jpg                       ffmpeg-php-0.6.0.tbz2                Linux                                           news-closeup.xsl     s3.jpg</span></span>
<span class="line"><span>cmslogs                         gmd-latest.sql.tar.bz2               Malware                                         newsletter1.html     sshdallow</span></span>
<span class="line"><span>epel-release-6-5.noarch.rpm     json-1.2.1                           movies_list.php                                 pollbeta.sql</span></span>
<span class="line"><span>ffmpeg-php-0.6.0                json-1.2.1.tgz                       my_next_artical_v2.php                          pollbeta.tar.bz2</span></span></code></pre></div><h4 id="步驟-5-使用-df-ht-命令檢查掛載點" tabindex="-1">步驟 5：使用 df -hT 命令檢查掛載點 <a class="header-anchor" href="#步驟-5-使用-df-ht-命令檢查掛載點" aria-label="Permalink to “步驟 5：使用 df -hT 命令檢查掛載點”">​</a></h4><p>如果你運行 df -hT命令，你將會看到遠程文件系統的掛載點。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># df -hT</span></span></code></pre></div><p>樣本輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Filesystem                          Type        Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>udev                                devtmpfs    730M     0  730M   0% /dev</span></span>
<span class="line"><span>tmpfs                               tmpfs       150M  4.9M  145M   4% /run</span></span>
<span class="line"><span>/dev/sda1                           ext4         31G  5.5G   24G  19% /</span></span>
<span class="line"><span>tmpfs                               tmpfs       749M  216K  748M   1% /dev/shm</span></span>
<span class="line"><span>tmpfs                               tmpfs       5.0M  4.0K  5.0M   1% /run/lock</span></span>
<span class="line"><span>tmpfs                               tmpfs       749M     0  749M   0% /sys/fs/cgroup</span></span>
<span class="line"><span>tmpfs                               tmpfs       150M   44K  150M   1% /run/user/1000</span></span>
<span class="line"><span>tecmint@192.168.0.102:/home/tecmint fuse.sshfs  324G   55G  253G  18% /mnt/tecmint</span></span></code></pre></div><h4 id="步驟-6-永久掛載遠程文件系統" tabindex="-1">步驟 6：永久掛載遠程文件系統 <a class="header-anchor" href="#步驟-6-永久掛載遠程文件系統" aria-label="Permalink to “步驟 6：永久掛載遠程文件系統”">​</a></h4><p>為了永久的掛載遠程的文件系統，你需要修改一個叫 <code>/etc/fstab</code> 的文件。照着做，使用你最喜歡的編輯器打開文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/fstab</span></span>
<span class="line"><span>$ sudo vi /etc/fstab     【基於 Debian/Ubuntu 的系統】</span></span></code></pre></div><p>移動到文件的底部並且添加下面的一行，保存文件並退出。下麪條目表示使用默認的設置掛載遠程的文件系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sshfs#tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint fuse.sshfs defaults 0 0</span></span></code></pre></div>`,23)),e("p",null,[s[4]||(s[4]=i("確保服務器之間允許 ",-1)),n(t,{href:"https://linux.cn/article-5444-1.html"},{default:a(()=>[...s[3]||(s[3]=[i("SSH 無密碼登錄",-1)])]),_:1}),s[5]||(s[5]=i("，這樣系統重啓之後才能自動掛載文件系統。",-1))]),s[21]||(s[21]=l(`<p>如果你的服務器配置為基於 SSH 密鑰的認證方式，請加入如下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sshfs#tecmint@x.x.x.x:/home/tecmint/ /mnt/tecmint fuse.sshfs IdentityFile=~/.ssh/id_rsa defaults 0 0</span></span></code></pre></div><p>接下來，你需要更新 fstab 文件使修改生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount -a</span></span>
<span class="line"><span>$ sudo mount -a   【基於 Debian/Ubuntu 的系統】</span></span></code></pre></div><h4 id="步驟-7-卸載遠程的文件系統" tabindex="-1">步驟 7：卸載遠程的文件系統 <a class="header-anchor" href="#步驟-7-卸載遠程的文件系統" aria-label="Permalink to “步驟 7：卸載遠程的文件系統”">​</a></h4><p>為了卸載遠程的文件系統，只需要發出以下的命令即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># umount /mnt/tecmint</span></span></code></pre></div><p>目前為止就這樣了，如果你在掛載遠程文件系統的時候遇到任何問題或者需要任何幫助，請通過評論聯繫我們，如果你感覺這篇文章非常有用，請分享給你的朋友們。</p><hr>`,9)),e("p",null,[s[7]||(s[7]=i("via: ",-1)),n(t,{href:"http://www.tecmint.com/sshfs-mount-remote-linux-filesystem-directory-using-ssh/"},{default:a(()=>[...s[6]||(s[6]=[i("http://www.tecmint.com/sshfs-mount-remote-linux-filesystem-directory-using-ssh/",-1)])]),_:1})]),e("p",null,[s[11]||(s[11]=i("作者：",-1)),n(t,{href:"http://www.tecmint.com/author/admin/"},{default:a(()=>[...s[8]||(s[8]=[i("Ravi Saive",-1)])]),_:1}),s[12]||(s[12]=i(" 譯者：",-1)),n(t,{href:"https://github.com/yangmingming"},{default:a(()=>[...s[9]||(s[9]=[i("yangmingming",-1)])]),_:1}),s[13]||(s[13]=i(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:a(()=>[...s[10]||(s[10]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[16]||(s[16]=i("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[14]||(s[14]=[i("LCTT",-1)])]),_:1}),s[17]||(s[17]=i(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:a(()=>[...s[15]||(s[15]=[i("Linux中國",-1)])]),_:1}),s[18]||(s[18]=i(" 榮譽推出",-1))])])}const y=p(d,[["render",u]]);export{x as __pageData,y as default};
